WITH lines AS (SELECT id, customer_id, created_at, coupon_codes, elem.product_id, elem.qty, elem.price FROM carts LATERAL VIEW OUTER EXPLODE(items) e AS elem) SELECT DATE_TRUNC('DAY', created_at) AS activity_day, APPROX_PERCENTILE(product_id, ARRAY(0.25, 0.5, 0.75)) AS product_id_quartiles, PERCENTILE_APPROX(price, ARRAY(0.25, 0.5, 0.75)) AS price_quartiles, PERCENTILE_APPROX(product_id, 0.9) AS product_id_p90 FROM lines GROUP BY DATE_TRUNC('DAY', created_at) HAVING product_id_p90 > 0;
